package org.rabochaya.projects;
import java.io.*;import java.nio.*;import java.nio.charset.*;import java.util.*;
/** Bounded, explicit WGS84/Latitude-Longitude Ozi calibration. Never opens the named image. */
public final class OziCalibration {
 public enum Encoding { UTF8("UTF-8"), WINDOWS1251("windows-1251"); final String charset;Encoding(String charset){this.charset=charset;} }
 public static final int MAX_BYTES=131072;public final String imageName;public final GeoRasterTransform transform;public final int controls;
 private OziCalibration(String name,GeoRasterTransform t,int count){imageName=name;transform=t;controls=count;}
 private static IOException bad(String s){return new IOException("Ozi: "+s);}
 private static String[] csv(String s)throws IOException{if(s.indexOf('"')>=0)throw bad("кавычки CSV пока не поддержаны");String[] a=s.split(",",-1);for(int i=0;i<a.length;i++)a[i]=a[i].trim();return a;}
 private static double number(String s)throws IOException{try{double v=Double.parseDouble(s);if(Double.isNaN(v)||Double.isInfinite(v))throw new NumberFormatException();return v;}catch(NumberFormatException e){throw bad("нечисловая калибровка");}}
 private static int integer(String s)throws IOException{double v=number(s);if(v!=Math.rint(v)||v<Integer.MIN_VALUE||v>Integer.MAX_VALUE)throw bad("ожидалось целое число");return (int)v;}
 private static String basename(String value)throws IOException{String p=value.replace('\\','/');if(p.isEmpty()||p.startsWith("//")||p.contains("://"))throw bad("недопустимое имя изображения");String[] parts=p.split("/",-1);for(String part:parts)if(part.equals(".."))throw bad("путь с .. запрещён");String name=parts[parts.length-1];if(name.isEmpty()||name.indexOf(':')>=0)throw bad("недопустимое имя изображения");for(int i=0;i<name.length();i++)if(Character.isISOControl(name.charAt(i)))throw bad("недопустимое имя изображения");return name;}
 private static double angle(String degrees,String minutes,String hemisphere,boolean latitude)throws IOException{double d=number(degrees),m=number(minutes),limit=latitude?90:180;if(d<0||d!=Math.rint(d)||d>limit||m<0||m>=60||d==limit&&m!=0)throw bad("некорректные градусы/минуты");if(!(latitude?(hemisphere.equals("N")||hemisphere.equals("S")):(hemisphere.equals("E")||hemisphere.equals("W"))))throw bad("неизвестное полушарие");return (d+m/60)*(hemisphere.equals("S")||hemisphere.equals("W")?-1:1);}
 /** Uses only the explicitly selected image name and measured dimensions. UTF-8/ASCII input. */
 public static OziCalibration read(InputStream input,String selectedImage,int width,int height)throws IOException{return read(input,selectedImage,width,height,Encoding.UTF8);}
 /** Only an explicit user-selected encoding; no fallback/detection. */
 public static OziCalibration read(InputStream input,String selectedImage,int width,int height,Encoding encoding)throws IOException{
  if(encoding==null)throw bad("нужен явный выбор кодировки");
  ByteArrayOutputStream data=new ByteArrayOutputStream();byte[] buffer=new byte[4096];int n;while((n=input.read(buffer))!=-1){if(n>MAX_BYTES-data.size())throw bad(".map больше 128 КиБ");data.write(buffer,0,n);}String text;try{text=Charset.forName(encoding.charset).newDecoder().onMalformedInput(CodingErrorAction.REPORT).onUnmappableCharacter(CodingErrorAction.REPORT).decode(ByteBuffer.wrap(data.toByteArray())).toString();}catch(CharacterCodingException e){throw bad("неверные байты для выбранной кодировки .map; кодировка не угадывается");}if(text.startsWith("\ufeff"))text=text.substring(1);if(text.indexOf('\0')>=0)throw bad("нулевой байт");String[] lines=text.split("\\r?\\n",-1);if(lines.length<5||lines.length>4096||!lines[0].trim().equals("OziExplorer Map Data File Version 2.2"))throw bad("неверный заголовок");for(String line:lines)if(line.length()>4096)throw bad("слишком длинная строка");
  String name=basename(lines[2].trim());if(!name.equalsIgnoreCase(basename(selectedImage)))throw bad("имя выбранного изображения не совпадает с .map");String[] datum=csv(lines[4]);if(datum.length<1||!datum[0].equals("WGS 84"))throw bad("поддержан только datum WGS 84");for(int i=1;i<datum.length;i++)if(!datum[i].isEmpty()&&!datum[i].equals("WGS 84")&&number(datum[i])!=0)throw bad("сдвиг датума не поддержан");
  ArrayList<double[]> points=new ArrayList<>();ArrayList<int[]> border=new ArrayList<>();HashSet<String> pointIds=new HashSet<>();boolean projection=false,setup=false,dimensions=false,msf=false;int declaredBorder=-1;
  for(int line=5;line<lines.length;line++){String[] a=csv(lines[line]);String tag=a[0];if(tag.equals("Map Projection")){if(projection||a.length<2||!a[1].equals("Latitude/Longitude"))throw bad("поддержана только Latitude/Longitude");projection=true;HashSet<String> flags=new HashSet<>();for(int i=2;i<a.length;i+=2){if(a[i].isEmpty()&&i==a.length-1)break;if(i+1>=a.length||!(a[i].equals("PolyCal")||a[i].equals("AutoCalOnly")||a[i].equals("BSBUseWPX"))||!flags.add(a[i])||!a[i+1].equals("No"))throw bad("альтернативная/нелинейная калибровка не поддержана");}}
   else if(tag.equals("Projection Setup")){if(setup)throw bad("повтор Projection Setup");setup=true;for(int i=1;i<a.length;i++)if(!a[i].isEmpty()&&number(a[i])!=0)throw bad("параметры проекции не поддержаны");}
   else if(tag.equals("MSF")){if(msf||a.length<2||number(a[1])!=1)throw bad("поддержан только MSF=1");msf=true;}
   else if(tag.equals("IWH")){if(dimensions||a.length<4||integer(a[2])!=width||integer(a[3])!=height)throw bad("размеры IWH не совпадают с изображением");dimensions=true;}
   else if(tag.matches("Point[0-9]+")){if(a.length<4)throw bad("повреждён Point");if(a[2].isEmpty()&&a[3].isEmpty())continue;if(a.length<17||!a[1].equals("xy")||!a[4].equals("in")||!pointIds.add(tag)||points.size()>=30)throw bad("некорректный/повторный Point или больше 30 точек");double x=number(a[2]),y=number(a[3]);if(x<0||y<0||x>width||y>height||!a[5].equals("deg"))throw bad("точка вне изображения или нет degrees");points.add(new double[]{x,y,angle(a[9],a[10],a[11],false),angle(a[6],a[7],a[8],true)});}
   else if(tag.equals("MMPNUM")){if(declaredBorder!=-1||a.length!=2||(declaredBorder=integer(a[1]))<0||declaredBorder>4)throw bad("поддержана только прямоугольная граница");}
   else if(tag.equals("MMPXY")){if(a.length!=4||border.size()>=4)throw bad("некорректная граница");int id=integer(a[1]),x=integer(a[2]),y=integer(a[3]);if(id!=border.size()+1||!(x==0||x==width)||!(y==0||y==height))throw bad("обрезанная/произвольная граница пока не поддержана");for(int[] p:border)if(p[0]==x&&p[1]==y)throw bad("повтор угла границы");border.add(new int[]{x,y});}
  }
  if(!projection||!setup||!dimensions||points.size()<3)throw bad("нужны projection/setup/IWH и минимум 3 контрольные точки");if(!border.isEmpty()&&(border.size()!=4||declaredBorder!=4)||declaredBorder>0&&border.size()!=declaredBorder)throw bad("неполная граница");
  for(int i=0;i<border.size();i++){int[] one=border.get(i),two=border.get((i+1)%border.size());if((one[0]==two[0])==(one[1]==two[1]))throw bad("граница должна идти по сторонам полного прямоугольника");}
  double area=0;double[] p=null,q=null,r=null;for(int i=0;i<points.size();i++)for(int j=i+1;j<points.size();j++)for(int k=j+1;k<points.size();k++){double[] aa=points.get(i),bb=points.get(j),cc=points.get(k);double value=(bb[0]-aa[0])*(cc[1]-aa[1])-(cc[0]-aa[0])*(bb[1]-aa[1]);if(Math.abs(value)>Math.abs(area)){area=value;p=aa;q=bb;r=cc;}}if(Math.abs(area)<Math.max(1,width*(double)height)*1e-10)throw bad("контрольные точки коллинеарны/неустойчивы");
  double a=((q[2]-p[2])*(r[1]-p[1])-(r[2]-p[2])*(q[1]-p[1]))/area,b=((q[0]-p[0])*(r[2]-p[2])-(r[0]-p[0])*(q[2]-p[2]))/area,c=p[2]-a*p[0]-b*p[1];double d=((q[3]-p[3])*(r[1]-p[1])-(r[3]-p[3])*(q[1]-p[1]))/area,e=((q[0]-p[0])*(r[3]-p[3])-(r[0]-p[0])*(q[3]-p[3]))/area,f=p[3]-d*p[0]-e*p[1],det=a*e-b*d;GeoRasterTransform transform;try{transform=new GeoRasterTransform(width,height,4326,false,a,b,c,d,e,f);}catch(IllegalArgumentException ex){throw bad(ex.getMessage());}
  for(double[] point:points){double lon=a*point[0]+b*point[1]+c-point[2],lat=d*point[0]+e*point[1]+f-point[3];double dx=(e*lon-b*lat)/det,dy=(-d*lon+a*lat)/det;if(Double.isNaN(dx)||Double.isInfinite(dx)||Double.isNaN(dy)||Double.isInfinite(dy)||Math.hypot(dx,dy)>.25)throw bad("контрольные точки не описывают affine привязку (0.25 px)");}
  return new OziCalibration(name,transform,points.size());
 }
}
